package com.aistock.prediction.modelcatalog;
import com.aistock.prediction.analysis.*;import com.aistock.prediction.verification.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.sql.Timestamp;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AnalysisPredictionSourceTest {
 final ObjectMapper m=new ObjectMapper();final Instant now=Instant.parse("2026-10-07T07:00:00Z");
 UUID add(ModelDatabaseFixture f,UUID u,String stock,String state,boolean hidden){var id=UUID.randomUUID();var s=m.createObjectNode();s.putObject("input").put("originDate","2026-09-30").put("originRawClose","100");var p=s.putObject("prediction").putArray("points");for(int i=1;i<=5;i++)p.addObject().put("step",i).put("targetDate",LocalDate.parse("2026-10-07").plusDays(i).toString()).put("referencePrice","101");f.jdbc.update("insert into forecast_request(prediction_id,user_id,operation_id,request_hash,model_id,instrument_id,horizon,state,model_json,snapshot_json,hidden,created_at,expires_at) values(?,?,?,?,?,?,5,?,'{\"artifactId\":\"model\"}',?,?,?,?)",id.toString(),u.toString(),UUID.randomUUID().toString(),"a".repeat(64),UUID.randomUUID().toString(),stock,state,"SUCCEEDED".equals(state)?s.toString():null,hidden,Timestamp.from(now),Timestamp.from(now.plusSeconds(100)));return id;}
 @Test void filtersBeforePaginationAndReadsOnlyOwnActiveSuccess(){var f=new ModelDatabaseFixture();var u=UUID.randomUUID();for(int i=0;i<12;i++)add(f,u,"SH600030","SUCCEEDED",false);var hidden=add(f,u,"SH600030","SUCCEEDED",true);var other=add(f,UUID.randomUUID(),"SH600030","SUCCEEDED",false);var wrong=add(f,u,"SH600000","SUCCEEDED",false);var failed=add(f,u,"SH600030","FAILED",false);add(f,u,"SH600030","RUNNING",false);var source=new AnalysisPredictionSource(f.jdbc,m,new VerificationQueryRepository(f.jdbc,m,Clock.fixed(now,ZoneOffset.UTC),18));assertEquals(12,source.options(u,"SH600030",1).path("total").asInt());assertEquals(10,source.options(u,"SH600030",1).path("items").size());assertEquals(2,source.options(u,"SH600030",2).path("items").size());assertThrows(com.aistock.common.BusinessException.class,()->source.read(u,"SH600030",hidden));assertThrows(com.aistock.common.BusinessException.class,()->source.read(u,"SH600030",other));assertThrows(com.aistock.common.BusinessException.class,()->source.read(u,"SH600030",wrong));assertThrows(com.aistock.common.BusinessException.class,()->source.read(u,"SH600030",failed));var id=UUID.fromString(source.options(u,"SH600030",1).path("items").get(0).path("predictionId").asText());assertEquals(id,source.read(u,"SH600030",id).record().predictionId());assertEquals(0,source.options(UUID.randomUUID(),"SH600030",1).path("total").asInt());}
}
